-- Preserve rich structures for evidence/metadata-only revisions; never
-- override a later human body edit with a stale imported composition.
do $$declare original public.visa_article_revisions;body jsonb;result jsonb;changed uuid;begin
 select r.* into original from public.visa_article_revisions r join private.rad_editorial_import_journal j on j.revision_id=r.id where j.article_id='4f753968-ebc8-5627-b169-bc3908d73b97' and j.locale='en';
 if original.title is distinct from 'Synthetic independent article' then raise exception 'Refuse non-synthetic fidelity fixture';end if;
 body:=original.body||jsonb_build_object('expected_revision',1,'summary','SYNTHETIC metadata edit only','request_key',gen_random_uuid());
 result:=public.save_visa_article_draft(body)->'data';
